private fun parityNear(p: PyreonXYPosition, x: Double, y: Double): Boolean = abs(p.x - x) < 1e-6 && abs(p.y - y) < 1e-6
private fun parityOpt(v: Double?, want: Double?): Boolean = if (v == null || want == null) v == null && want == null else abs(v - want) < 1e-6
private fun paritySnap(s: PyreonFlowSnapLines, x: Double?, y: Double?, px: Double, py: Double): Boolean = parityOpt(s.x, x) && parityOpt(s.y, y) && parityNear(s.snappedPosition, px, py)
private fun parityPoints(got: List<PyreonXYPosition>, want: List<Pair<Double, Double>>): Boolean {
    if (got.size != want.size) return false
    for (i in got.indices) { if (abs(got[i].x - want[i].first) >= 1e-6 || abs(got[i].y - want[i].second) >= 1e-6) return false }
    return true
}
private fun parityNodes(f: PyreonFlowState<NodeData>, want: List<Triple<String, Double, Double>>, tol: Double = 1e-6): Boolean {
    val got = f.nodes
    if (got.size != want.size) return false
    for (i in got.indices) { if (got[i].id != want[i].first || abs(got[i].position.x - want[i].second) >= tol || abs(got[i].position.y - want[i].third) >= tol) return false }
    return true
}
private fun parityEdges(f: PyreonFlowState<NodeData>, want: List<Triple<String, String, String>>): Boolean {
    val got = f.edges
    if (got.size != want.size) return false
    for (i in got.indices) { if (got[i].id != want[i].first || got[i].source != want[i].second || got[i].target != want[i].third) return false }
    return true
}
